sys_script_fix.script:
var list = new GlideRecord("x_58872_needit_rcca_reference");
// To update mispelling
list.addEncodedQuery("active=true^type=incident_source^value=Anasysis (defect, yield rates etc.)");
list.query();
while (list.next()){
	list.setValue('value','Analysis (defect, yield rates etc.)');
	list.update();
}
list.initialize();
list.addEncodedQuery("active=true^type=end_user_impacted^value=BEF Suppliers- Seats, Monuments, etc.");
list.query();
while (list.next()){
	list.setValue('value','BFE Suppliers- Seats, Monuments, etc.');
	list.update();
}
// To add new reference values
list.initialize();
list.addEncodedQuery("active=true^type=incident_source^value=Safety");
list.query();
if (!list.next()){
	list.setValue('type','incident_source');
	list.setValue('value','Safety');
	list.setValue('active','true');
	list.setValue('filed_id',60);
	list.insert();
}
// To add new reference values
list.initialize();
list.addEncodedQuery("active=true^type=incident_source^value=Certification");
list.query();
if (!list.next()){
	list.setValue('type','incident_source');
	list.setValue('value','Certification');
	list.setValue('active','true');
	list.setValue('filed_id',60);
	list.insert();
}
